import React, { useState, useEffect } from "react";
import { Button, Modal, Form } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Modal de edición
  const [showModal, setShowModal] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [updatedData, setUpdatedData] = useState({});

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      const res = await fetch("http://localhost/api/comandes");
      if (!res.ok) throw new Error("Error al obtenir les comandes");
      const data = await res.json();
      setOrders(Array.isArray(data.dades) ? data.dades : []);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setError(err.message);
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Segur que vols eliminar aquesta comanda?")) return;
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`http://localhost/api/comandes/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("Error al eliminar la comanda");
      fetchOrders(); // refresca la lista
    } catch (err) {
      console.error(err);
      alert(err.message);
    }
  };

  const handleEdit = (order) => {
    setSelectedOrder(order);
    setUpdatedData({
      tipus: order.tipus,
      client_id: order.client_id,
      proveidor_id: order.proveidor_id,
      data: order.data,
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`http://localhost/api/comandes/${selectedOrder.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(updatedData),
      });
      if (!res.ok) throw new Error("Error al actualizar la comanda");
      setShowModal(false);
      fetchOrders();
    } catch (err) {
      console.error(err);
      alert(err.message);
    }
  };

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p className="text-danger">Error: {error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div className="row">
      {orders.map((order) => (
        <div key={order.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">ID: {order.id}</h5>
              <p className="card-text">
                <strong>Data:</strong> {order.data}
              </p>
              <p className="card-text">
                <strong>Tipus:</strong> {order.tipus}
              </p>
              <p className="card-text">
                <strong>Client:</strong> {order.client?.nom || "—"}
              </p>
              <p className="card-text">
                <strong>Proveïdor:</strong> {order.proveidor?.nom || "—"}
              </p>

              <Button
                variant="primary"
                className="me-2"
                onClick={() => handleEdit(order)}
              >
                Editar
              </Button>
              <Button variant="danger" onClick={() => handleDelete(order.id)}>
                Eliminar
              </Button>
            </div>
          </div>
        </div>
      ))}

      {/* Modal de edición */}
      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Editar Comanda</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Tipus</Form.Label>
              <Form.Control
                type="text"
                value={updatedData.tipus || ""}
                onChange={(e) =>
                  setUpdatedData({ ...updatedData, tipus: e.target.value })
                }
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Data</Form.Label>
              <Form.Control
                type="datetime-local"
                value={updatedData.data || ""}
                onChange={(e) =>
                  setUpdatedData({ ...updatedData, data: e.target.value })
                }
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Client ID</Form.Label>
              <Form.Control
                type="number"
                value={updatedData.client_id || ""}
                onChange={(e) =>
                  setUpdatedData({ ...updatedData, client_id: e.target.value })
                }
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Proveïdor ID</Form.Label>
              <Form.Control
                type="number"
                value={updatedData.proveidor_id || ""}
                onChange={(e) =>
                  setUpdatedData({ ...updatedData, proveidor_id: e.target.value })
                }
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel·lar
          </Button>
          <Button variant="primary" onClick={handleSave}>
            Guardar
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}

export default OrdersList;
